using Store;

namespace Store.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup() => _cart = new ShoppingCart();

    // ──────────────────────────────────────────────
    //  AddItem
    // ──────────────────────────────────────────────

    [TestMethod]
    public void AddItem_SingleItem_AppearsInCart()
    {
        _cart.AddItem("SKU-1", 2, 9.99m);

        Assert.AreEqual(1, _cart.Items.Count);
        Assert.AreEqual(2, _cart.Items["SKU-1"].Quantity);
        Assert.AreEqual(9.99m, _cart.Items["SKU-1"].Price);
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_QuantitiesAccumulate()
    {
        _cart.AddItem("SKU-1", 1, 5.00m);
        _cart.AddItem("SKU-1", 3, 5.00m);

        Assert.AreEqual(1, _cart.Items.Count);
        Assert.AreEqual(4, _cart.Items["SKU-1"].Quantity);
    }

    [TestMethod]
    public void AddItem_MultipleSkus_AllTracked()
    {
        _cart.AddItem("A", 1, 1.00m);
        _cart.AddItem("B", 2, 2.00m);

        Assert.AreEqual(2, _cart.Items.Count);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void AddItem_InvalidSku_Throws(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(() => _cart.AddItem(sku!, 1, 1.00m));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    public void AddItem_InvalidQuantity_Throws(int quantity)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _cart.AddItem("SKU-1", quantity, 1.00m));
    }

    [TestMethod]
    public void AddItem_NegativePrice_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _cart.AddItem("SKU-1", 1, -0.01m));
    }

    [TestMethod]
    public void AddItem_ZeroPrice_Allowed()
    {
        _cart.AddItem("FREEBIE", 1, 0m);

        Assert.AreEqual(0m, _cart.Items["FREEBIE"].Price);
    }

    // ──────────────────────────────────────────────
    //  RemoveItem
    // ──────────────────────────────────────────────

    [TestMethod]
    public void RemoveItem_ExistingSku_RemovesIt()
    {
        _cart.AddItem("SKU-1", 1, 5.00m);
        _cart.RemoveItem("SKU-1");

        Assert.AreEqual(0, _cart.Items.Count);
    }

    [TestMethod]
    public void RemoveItem_NonExistentSku_ThrowsKeyNotFound()
    {
        Assert.ThrowsException<KeyNotFoundException>(() => _cart.RemoveItem("NOPE"));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void RemoveItem_InvalidSku_Throws(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(() => _cart.RemoveItem(sku!));
    }

    // ──────────────────────────────────────────────
    //  CalculateTotal
    // ──────────────────────────────────────────────

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_SingleItem_ReturnsCorrectTotal()
    {
        _cart.AddItem("SKU-1", 3, 10.00m);

        Assert.AreEqual(30.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_MultipleItems_SumsCorrectly()
    {
        _cart.AddItem("A", 2, 5.50m);  // 11.00
        _cart.AddItem("B", 1, 3.25m);  //  3.25

        Assert.AreEqual(14.25m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_AfterRemoval_Recalculates()
    {
        _cart.AddItem("A", 1, 10.00m);
        _cart.AddItem("B", 1, 20.00m);
        _cart.RemoveItem("A");

        Assert.AreEqual(20.00m, _cart.CalculateTotal());
    }

    // ──────────────────────────────────────────────
    //  ApplyCoupon
    // ──────────────────────────────────────────────

    [TestMethod]
    public void ApplyCoupon_ValidCode_SetsAppliedCoupon()
    {
        _cart.ApplyCoupon("SAVE10");

        Assert.AreEqual("SAVE10", _cart.AppliedCoupon);
    }

    [TestMethod]
    public void ApplyCoupon_InvalidCode_Throws()
    {
        Assert.ThrowsException<ArgumentException>(() => _cart.ApplyCoupon("BOGUS"));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void ApplyCoupon_NullOrWhitespace_Throws(string? code)
    {
        Assert.ThrowsException<ArgumentException>(() => _cart.ApplyCoupon(code!));
    }

    [TestMethod]
    public void ApplyCoupon_ReplacePreviousCoupon()
    {
        _cart.ApplyCoupon("SAVE10");
        _cart.ApplyCoupon("SAVE20");

        Assert.AreEqual("SAVE20", _cart.AppliedCoupon);
    }

    // ──────────────────────────────────────────────
    //  CalculateTotal + Coupon integration
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow("SAVE10", 90.00)]
    [DataRow("SAVE20", 80.00)]
    [DataRow("HALF",   50.00)]
    public void CalculateTotal_WithCoupon_AppliesDiscount(string code, double expected)
    {
        _cart.AddItem("SKU-1", 1, 100.00m);
        _cart.ApplyCoupon(code);

        Assert.AreEqual((decimal)expected, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_CouponOnMultipleItems_DiscountsFullSubtotal()
    {
        _cart.AddItem("A", 2, 25.00m);  // 50
        _cart.AddItem("B", 1, 50.00m);  // 50
        _cart.ApplyCoupon("SAVE10");     // subtotal 100 → 90

        Assert.AreEqual(90.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_NoCoupon_NoDiscount()
    {
        _cart.AddItem("SKU-1", 1, 100.00m);

        Assert.IsNull(_cart.AppliedCoupon);
        Assert.AreEqual(100.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_CouponOnEmptyCart_ReturnsZero()
    {
        _cart.ApplyCoupon("HALF");

        Assert.AreEqual(0m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_RoundsToTwoDecimalPlaces()
    {
        _cart.AddItem("SKU-1", 3, 9.99m); // 29.97
        _cart.ApplyCoupon("SAVE10");       // 29.97 * 0.9 = 26.973

        Assert.AreEqual(26.97m, _cart.CalculateTotal());
    }
}

